245	/// A ring's geometry and where its segments are, the state both
246	/// endpoints start from.
247	///
248	/// - The segments are byte offsets from the pool's buffer array,
249	///   the same numbers in every process, and `base` is that array
250	///   in this one, so the table could be shared as it is and a
251	///   slot access is one add over v3's.
252	#[derive(Clone, Copy)]
253	struct Segments {
254	    /// The pool's buffer array in this process.
255	    base: *mut u8,
256	    /// The slot array of each segment, `seg_count` of them, as an
257	    /// offset from `base`.
258	    slots: [usize; MAX_SEGMENTS as usize],
259	    /// Segment 0's header as an offset from `base`: `given` and
260	    /// the claims line live there.
261	    header0: usize,
262	    /// Slot size N in bytes.
263	    slot_size: u32,
264	    /// Segment depth M, a power of two.
265	    capacity: u32,
266	    /// Slot-position mask (`capacity - 1`).
267	    mask: u32,
268	    /// Segments in the ring.
269	    seg_count: u32,
270	}
271	
272	impl Segments {
273	    /// The seq word of the slot at free-running `idx` in segment
274	    /// `seg`.
275	    fn seq(&self, seg: u32, idx: u32) -> &AtomicU32 {
276	        let slot = crate::slot_ptr(self.slot_base(seg), idx, self.mask, self.slot_size);
277	        // SAFETY: seg < seg_count and the slot is in bounds of
278	        // that segment's buffer, line-aligned, so its first word
279	        // is an aligned AtomicU32, shared atomic state by design.
280	        unsafe { &*(slot as *const AtomicU32) }
281	    }
282	
283	    /// The body of the slot at free-running `idx` in segment
284	    /// `seg`, behind its [`SLOT_HEADER_BYTES`].
285	    fn body(&self, seg: u32, idx: u32) -> *mut u8 {
286	        let slot = crate::slot_ptr(self.slot_base(seg), idx, self.mask, self.slot_size);
287	        // SAFETY: SLOT_HEADER_BYTES < CACHE_LINE_SIZE <= slot_size,
288	        // so the body starts inside the slot.
289	        unsafe { slot.add(SLOT_HEADER_BYTES) }
290	    }
291	
292	    /// Segment `seg`'s slot array in this process.
293	    #[inline]
294	    fn slot_base(&self, seg: u32) -> *mut u8 {
295	        // SAFETY: seg < seg_count, and the offset was computed by
296	        // init or attach from a buffer index the pool validated,
297	        // so it stays inside the buffer array.
298	        unsafe { self.base.add(self.slots[seg as usize]) }
299	    }
300	
301	    /// Segment 0's header, the ring's control block.
302	    fn header0(&self) -> &SegmentHeader {
303	        // SAFETY: header0 is the front of segment 0's buffer,
304	        // line-aligned, which lives as long as the pool region the
305	        // ring borrows from, and every field is atomic.
306	        unsafe { &*(self.base.add(self.header0) as *const SegmentHeader) }
307	    }
308	
309	    /// The consumer's give-back word.
310	    fn given(&self) -> &AtomicU32 {
311	        &self.header0().info.given
312	    }
313	
314	    /// The claims line, the roles and the checkpoints.
315	    fn claims(&self) -> &Claims {
316	        &self.header0().claims
317	    }
318	
319	    /// Segment `seg`'s info line, where its resume positions are.
320	    fn info(&self, seg: u32) -> &Info {
321	        // SAFETY: seg < seg_count, and the segment's header sits
322	        // just ahead of its slots, the front of a buffer that
323	        // lives as long as the pool region, every field atomic.
324	        unsafe {
325	            &(*(self
326	                .base
327	                .add(self.slots[seg as usize] - size_of::<SegmentHeader>())
328	                as *const SegmentHeader))
329	                .info
330	        }
331	    }
332	
333	    /// Checkpoint a producer switch from `from` into `to`, ahead
334	    /// of the MOVED commit that publishes it.
335	    ///
336	    /// - `left_at` is the position after the MOVED slot, where a
337	    ///   later stint in `from` starts, and `taken` the take word
338	    ///   with `to` flipped.
339	    /// - The resume position goes first, ahead of the intent: an
340	    ///   entry for the segment still current is read by nobody.
341	    /// - Every store is Release, so a reader that sees one sees
342	    ///   the stores before it, the intent included.
343	    /// - Out of line and cold, as its two siblings are, so the
344	    ///   message path's code stays what it was without them.
345	    #[cold]
346	    #[inline(never)]
347	    fn producer_switch(&self, from: u32, to: u32, left_at: u32, taken: u32) {
348	        let c = self.claims();
349	        self.info(from)
350	            .prod_resume
351	            .store(left_at, Ordering::Release);
352	        c.prod_switch.store(
353	            switch_intent(from, to, (taken >> to) & 1),
354	            Ordering::Release,
355	        );
356	        c.prod_taken.store(taken, Ordering::Release);
357	        c.prod_cur.store(to, Ordering::Release);
358	    }
359	
360	    /// Checkpoint a consumer switch from `from` into `to`, ahead
361	    /// of the release that frees the MOVED slot, as
362	    /// [`producer_switch`](Segments::producer_switch) does.
363	    ///
364	    /// - `given` is the give-back word with `from` flipped, stored
365	    ///   to the shared word after the release, so the intent
366	    ///   records the bit it leaves for `from`.
367	    #[cold]
368	    #[inline(never)]
369	    fn consumer_switch(&self, from: u32, to: u32, left_at: u32, given: u32) {
370	        let c = self.claims();
371	        self.info(from)
372	            .cons_resume
373	            .store(left_at, Ordering::Release);
374	        c.cons_switch.store(
375	            switch_intent(from, to, (given >> from) & 1),
376	            Ordering::Release,
377	        );
378	        c.cons_cur.store(to, Ordering::Release);
379	    }
380	
381	    /// Clear an intent word once its switch's last shared store
382	    /// is made.
383	    #[cold]
384	    #[inline(never)]
385	    fn switch_done(intent: &AtomicU32) {
386	        // Release: a reader that sees the word clear sees the
387	        // switch's stores, the seq word's among them.
388	        intent.store(0, Ordering::Release);
389	    }
390	
391	    /// Take a set intent word apart, refusing segments the ring
392	    /// does not have.
393	    fn intent(&self, word: u32) -> Result<Intent, Error> {
394	        let from = word & SEG_MASK;
395	        let to = (word >> SWITCH_TO_SHIFT) & SEG_MASK;
396	        let bit = (word >> SWITCH_BIT_SHIFT) & 1;
397	        let fits = word & SWITCH_SET != 0 && from < self.seg_count && to < self.seg_count;
398	        if !fits || from == to {
399	            return Err(Error::BadCheckpoint);
400	        }
401	        Ok(Intent { from, to, bit })
402	    }
403	
404	    /// Every segment's resume position, one side's, from the info
405	    /// lines.
406	    fn resume_table(&self, side: impl Fn(&Info) -> &AtomicU32) -> [u32; MAX_SEGMENTS as usize] {
407	        let mut resume = [0; MAX_SEGMENTS as usize];
408	        for seg in 0..self.seg_count {
409	            resume[seg as usize] = side(self.info(seg)).load(Ordering::Acquire);
410	        }
411	        resume
412	    }
413	
414	    /// The producer's state from the region, for a claim of a
415	    /// released role (`released`) or a takeover of a held one.
416	    ///
417	    /// - A set intent names the switch the holder died inside. Its
418	    ///   MOVED commit never happened when the slot it left is still
419	    ///   claimable: undo, and continue at that slot. Otherwise
420	    ///   finish, at the start of the segment entered, where the
421	    ///   holder had written nothing. Either way the repaired
422	    ///   checkpoint is written back and the intent cleared.
423	    /// - A clear intent leaves `cur` and `taken` exact, and the
424	    ///   position is the one `release` wrote or, for a takeover,
425	    ///   the scan's.
426	    #[cold]
427	    fn load_producer(&self, released: bool) -> Result<Checkpoint, Error> {
428	        let c = self.claims();
429	        let mut cur = c.prod_cur.load(Ordering::Acquire);
430	        let mut taken = c.prod_taken.load(Ordering::Acquire);
431	        let intent = c.prod_switch.load(Ordering::Acquire);
432	        let resume = self.resume_table(|info| &info.prod_resume);
433	        let pos = if intent != 0 {
434	            let Intent { from, to, bit } = self.intent(intent)?;
435	            let p = resume[from as usize].wrapping_sub(1);
436	            let pos = if self.seq(from, p).load(Ordering::Acquire) == seq_of(p) {
437	                cur = from;
438	                taken = (taken & !(1 << to)) | ((bit ^ 1) << to);
439	                p
440	            } else {
441	                cur = to;
442	                taken = (taken & !(1 << to)) | (bit << to);
443	                resume[to as usize]
444	            };
445	            c.prod_taken.store(taken, Ordering::Release);
446	            c.prod_cur.store(cur, Ordering::Release);
447	            Segments::switch_done(&c.prod_switch);
448	            pos
449	        } else if cur >= self.seg_count {
450	            return Err(Error::BadCheckpoint);
451	        } else if released {
452	            c.prod_pos.load(Ordering::Acquire)
453	        } else {
454	            // The window of positions the slots last held ends just
455	            // before the producer's.
456	            let (oldest, _) = self.window(cur)?;
457	            lift(resume[cur as usize], oldest.wrapping_add(self.capacity))
458	        };
459	        Ok(Checkpoint {
460	            cur,
461	            pos,
462	            free_set: taken,
463	            resume,
464	        })
465	    }
466	
467	    /// The consumer's state from the region, as
468	    /// [`load_producer`](Segments::load_producer) loads the
469	    /// producer's.
470	    ///
471	    /// - A set intent: the release never happened when the slot it
472	    ///   left still holds the MOVED commit, so undo and read that
473	    ///   message again. Otherwise finish: the give-back word gets
474	    ///   the bit the intent names, which the holder may have died
475	    ///   before storing, and the consumer starts where it enters.
476	    /// - A clear intent: the position `release` wrote or, for a
477	    ///   takeover, the oldest committed slot the scan finds.
478	    #[cold]
479	    fn load_consumer(&self, released: bool) -> Result<Checkpoint, Error> {
480	        let c = self.claims();
481	        let mut cur = c.cons_cur.load(Ordering::Acquire);
482	        let mut given = self.given().load(Ordering::Acquire);
483	        let intent = c.cons_switch.load(Ordering::Acquire);
484	        let resume = self.resume_table(|info| &info.cons_resume);
485	        let pos = if intent != 0 {
486	            let Intent { from, to, bit } = self.intent(intent)?;
487	            let m = resume[from as usize].wrapping_sub(1);
488	            let moved =
489	                seq_of(m.wrapping_add(self.capacity).wrapping_add(1)) | MOVED | (to << SEG_SHIFT);
490	            let pos = if self.seq(from, m).load(Ordering::Acquire) == moved {
491	                cur = from;
492	                given = (given & !(1 << from)) | ((bit ^ 1) << from);
493	                m
494	            } else {
495	                cur = to;
496	                given = (given & !(1 << from)) | (bit << from);
497	                resume[to as usize]
498	            };
499	            self.given().store(given, Ordering::Release);
500	            c.cons_cur.store(cur, Ordering::Release);
501	            Segments::switch_done(&c.cons_switch);
502	            pos
503	        } else if cur >= self.seg_count {
504	            return Err(Error::BadCheckpoint);
505	        } else if released {
506	            c.cons_pos.load(Ordering::Acquire)
507	        } else {
508	            let (oldest, unread) = self.window(cur)?;
509	            let first = oldest.wrapping_add(self.capacity).wrapping_sub(unread);
510	            lift(resume[cur as usize], first)
511	        };
512	        Ok(Checkpoint {
513	            cur,
514	            pos,
515	            free_set: given,
516	            resume,
517	        })
518	    }
519	
520	    /// The window of positions segment `seg`'s slots last held,
521	    /// from their seq words: its oldest position, modulo
522	    /// `2^SEQ_BITS`, and how many of its newest are committed.
523	    ///
524	    /// - Slot `i` last held position `q`, `q = i` modulo the depth,
525	    ///   released (seq `q + M`) or committed (seq `q + M + 1`), and
526	    ///   the positions are the `M` before the producer's in the
527	    ///   segment, the committed ones the newest, from the
528	    ///   consumer's on. The seq's low bits tell released from
529	    ///   committed, which at depth 1 they cannot.
530	    /// - A live producer committing while the scan reads can make
531	    ///   one read disagree with the rest, so the scan runs again,
532	    ///   and a live consumer's releases change no position. With
533	    ///   the other side dead the words settle, the producer's
534	    ///   within a ring's capacity of commits, so a bounded number
535	    ///   of disagreeing scans means words the ring never wrote.
536	    #[cold]
537	    fn window(&self, seg: u32) -> Result<(u32, u32), Error> {
538	        if self.capacity < 2 {
539	            return Err(Error::BadCapacity);
540	        }
541	        const SCANS: u32 = 1024;
542	        for _ in 0..SCANS {
543	            if let Some(found) = self.scan(seg) {
544	                return Ok(found);
545	            }
546	        }
547	        Err(Error::BadCheckpoint)
548	    }
549	
550	    /// One scan of [`window`](Segments::window), `None` when the
551	    /// words do not form one window.
552	    fn scan(&self, seg: u32) -> Option<(u32, u32)> {
553	        let m = self.capacity;
554	        // Offsets from slot 0's position, signed over SEQ_BITS.
555	        let offset = |q: u32, base: u32| {
556	            let d = q.wrapping_sub(base) & SEQ_MASK;
557	            if d >= 1 << (SEQ_BITS - 1) {
558	                d as i64 - (1i64 << SEQ_BITS)
559	            } else {
560	                d as i64
561	            }
562	        };
563	        let (mut base, mut lo, mut hi) = (0u32, i64::MAX, i64::MIN);
564	        let (mut unread, mut lo_unread) = (0u32, i64::MAX);
565	        for i in 0..m {
566	            let v = self.seq(seg, i).load(Ordering::Acquire) & SEQ_MASK;
567	            let (q, committed) = if v & self.mask == i {
568	                (v.wrapping_sub(m) & SEQ_MASK, false)
569	            } else if v & self.mask == (i + 1) & self.mask {
570	                (v.wrapping_sub(m).wrapping_sub(1) & SEQ_MASK, true)
571	            } else {
572	                return None;
573	            };
574	            if i == 0 {
575	                base = q;
576	            }
577	            let d = offset(q, base);
578	            lo = lo.min(d);
579	            hi = hi.max(d);
580	            if committed {
581	                unread += 1;
582	                lo_unread = lo_unread.min(d);
583	            }
584	        }
585	        // M distinct positions, one per slot, span exactly M, and
586	        // the committed ones are the newest.
587	        let whole = hi - lo == (m - 1) as i64;
588	        let tail = unread == 0 || lo_unread == hi - unread as i64 + 1;
589	        if !whole || !tail {
590	            return None;
591	        }
592	        Some((base.wrapping_add(lo as u32) & SEQ_MASK, unread))
593	    }
594	
595	    /// The table every endpoint starts from, built the same way
596	    /// by `init` and `attach`: each segment's slot array as an
597	    /// offset from the pool's buffer array.
598	    fn load(
599	        base: *mut u8,
600	        buf_size: usize,
601	        indices: &[u32; MAX_SEGMENTS as usize],
602	        slot_size: u32,
603	        seg_capacity: u32,
604	        seg_count: u32,
605	    ) -> Self {
606	        let mut slots = [0usize; MAX_SEGMENTS as usize];
607	        for seg in 0..seg_count as usize {
608	            slots[seg] = indices[seg] as usize * buf_size + size_of::<SegmentHeader>();
609	        }
610	        Segments {
611	            base,
612	            slots,
613	            header0: indices[0] as usize * buf_size,
614	            slot_size,
615	            capacity: seg_capacity,
616	            mask: seg_capacity - 1,
617	            seg_count,
618	        }
619	    }
620	
621	    /// The producer role's word in the claims line.
622	    fn producer_role(&self) -> &AtomicU32 {
623	        &self.header0().claims.producer
624	    }
625	
626	    /// The consumer role's word in the claims line.
627	    fn consumer_role(&self) -> &AtomicU32 {
628	        &self.header0().claims.consumer
629	    }
630	
631	    /// Give `role` back as released, if `holder` still holds it.
632	    ///
633	    /// - A CAS from the holder's own id, so an endpoint whose role
634	    ///   was taken over releases nothing.
635	    fn release_role(role: &AtomicU32, holder: u32) {
636	        // Release: the next claimant's AcqRel sees everything this
637	        // endpoint did.
638	        let _ = role.compare_exchange(holder, ROLE_RELEASED, Ordering::Release, Ordering::Relaxed);
639	    }
640	
641	    /// Every segment's bit.
642	    fn all(&self) -> u32 {
643	        if self.seg_count == MAX_SEGMENTS {
644	            u32::MAX
645	        } else {
646	            (1 << self.seg_count) - 1
647	        }
648	    }
649	}
